using Microsoft.EntityFrameworkCore;
using System.Net;
using System.Net.Mail;
namespace Society.Api;
public record WelcomeSend(Guid MembershipId,string TemplateId);
public record WelcomeTemplate(string Id,string Kind,string Name,string Heading,string Intro,string Next,string Color);
public static class MemberWelcome {
 public static readonly WelcomeTemplate[] Templates=[
 new("individual-classic","Individual","Official welcome","Welcome to your professional community","We are pleased to welcome you as an Individual Member of {society}. Your membership brings you into a community committed to learning, meaningful connections and professional growth.","Sign in to review your membership details, complete your profile and explore the resources available to you.","#155e75"),
 new("individual-connect","Individual","Connect & collaborate","Great ideas begin with connection","Welcome to {society}. We look forward to the perspectives, experience and enthusiasm you bring to our community as an Individual Member.","Explore your chapter, discover upcoming activities and connect with opportunities to exchange knowledge and collaborate.","#4338ca"),
 new("individual-start","Individual","Your first steps","Your membership journey starts here","It is a pleasure to welcome you to {society}. We want your first steps as an Individual Member to be clear, useful and rewarding.","Start by checking your profile and membership details. Then visit the resources area and your chapter’s activities to plan your next step.","#047857"),
 new("institutional-classic","Institutional","Institutional welcome","Welcome to our institutional network","We are delighted to welcome your institution as an Institutional Member of {society}. We value your commitment to building stronger connections between institutions, professionals and the wider community.","Your authorized representative can sign in to review institutional membership details and explore the tools and resources available under your membership.","#155e75"),
 new("institutional-partnership","Institutional","Partnership & impact","A shared commitment to progress","Thank you for joining {society} as an Institutional Member. We look forward to a constructive association built on knowledge exchange, participation and shared professional interests.","Review your institution’s profile and authorized contacts, then explore chapter activities and opportunities for your institution to participate.","#7c3aed"),
 new("institutional-onboarding","Institutional","Institution onboarding","Help your institution get started","Welcome to {society}. Your institution’s membership is an opportunity to engage your community with the resources and activities available through the society.","Ask your authorized representative to verify the institution profile and review the Organization team & chapters area. Eligible team access follows your institution’s membership validity.","#0369a1")];
 public static IQueryable<Membership> Scope(AppDb db,Guid tenant,Guid user,bool platform){var q=db.Memberships.Where(m=>m.TenantId==tenant);if(platform)return q;var read=Access.UnitsFor(db,tenant,user,"members.read").Select(u=>u.Id);var send=Access.UnitsFor(db,tenant,user,"communications.send").Select(u=>u.Id);return q.Where(m=>read.Contains(m.ChapterId)&&send.Contains(m.ChapterId));}
 public static bool Eligible(Membership m)=>m.Status=="Active"&&!m.PendingPayment&&m.EffectiveFrom<=DateTimeOffset.UtcNow&&(m.EndsAt==null||m.EndsAt>DateTimeOffset.UtcNow)&&!string.IsNullOrWhiteSpace(m.Number);
 public static async Task<(string Email,Guid? User)> Contact(AppDb db,Membership m){var p=await db.Persons.SingleAsync(p=>p.Id==m.PersonId);var email=p.UserId==null?MembershipService.Json(m.Profile)["email"]?.ToString():await db.Users.Where(u=>u.Id==p.UserId).Select(u=>u.Email).SingleOrDefaultAsync();return(email??"",p.UserId);}
 public static async Task<bool> Allowed(AppDb db,Membership m,string email,Guid? user){if(!Eligible(m)||!MailAddress.TryCreate(email,out _)||!CommunityService.CommunicationAllowed(m.Privacy))return false;if(user!=null&&await db.Set<CommunicationPreference>().AnyAsync(p=>p.TenantId==m.TenantId&&p.UserId==user&&!p.Email))return false;return !await db.Set<CommunicationSuppression>().AnyAsync(s=>s.TenantId==m.TenantId&&s.Channel=="Email"&&s.DestinationHash==CommunityService.Hash(email.ToLowerInvariant()));}
 public static async Task<object> Preview(AppDb db,IConfiguration config,Membership m,string templateId,string? recipientOverride=null){var template=Templates.SingleOrDefault(t=>t.Id==templateId)??throw new DomainException("Choose a welcome template");var kind=await db.MembershipCategories.Where(c=>c.TenantId==m.TenantId&&c.Id==m.CategoryId).Select(c=>c.Kind).SingleAsync();if(kind!=template.Kind)throw new DomainException("Choose a template matching this membership type");var society=await db.Tenants.Where(t=>t.Id==m.TenantId).Select(t=>t.Name).SingleAsync();var name=await db.Persons.Where(p=>p.Id==m.PersonId).Select(p=>p.FullName).SingleAsync();var chapter=await db.Units.Where(u=>u.Id==m.ChapterId&&u.TenantId==m.TenantId).Select(u=>u.Name).SingleAsync();var contact=await Contact(db,m);string H(string? s)=>WebUtility.HtmlEncode(s)??"";var url=(config["PublicUrl"]??"").TrimEnd('/')+"/app/membership";var subject=$"Welcome to {society} | Membership ID {m.Number}";var expiry=m.EndsAt==null?"No expiry recorded":PlatformMemberAdmin.Date(m.EndsAt.Value.AddTicks(-1)).ToString("dd MMM yyyy");var html=$"""
 <!doctype html><html><body style="margin:0;background:#f1f5f9;font-family:Arial,sans-serif;color:#183047"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="padding:28px 12px"><table role="presentation" width="100%" style="max-width:640px;margin:auto;background:white;border:1px solid #dbe5ee;border-radius:12px" cellpadding="0" cellspacing="0"><tr><td style="padding:30px;background:{template.Color};color:white"><p style="font-size:12px;letter-spacing:2px">{H(society.ToUpperInvariant())} · MEMBERSHIP</p><h1 style="font-size:28px;line-height:1.3">{H(template.Heading)}</h1></td></tr><tr><td style="padding:30px"><p>Dear {H(name)},</p><p style="line-height:1.8">{H(template.Intro.Replace("{society}",society))}</p><div style="background:#f0f7fb;border-left:4px solid {template.Color};padding:20px;margin:24px 0"><p style="font-size:12px;margin:0">YOUR MEMBERSHIP ID</p><p style="font-size:24px;font-weight:bold;margin:10px 0">{H(m.Number)}</p><p>{H(kind)} Member · {H(chapter)}</p><p style="font-size:13px">Valid from {PlatformMemberAdmin.Date(m.EffectiveFrom):dd MMM yyyy}<br>Valid till {H(expiry)}</p></div><h2 style="font-size:18px">Make the most of your membership</h2><p style="line-height:1.8">{H(template.Next)}</p><p style="margin:28px 0"><a href="{H(url)}" style="display:inline-block;background:{template.Color};color:white;text-decoration:none;padding:14px 22px;border-radius:6px">Open your member portal</a></p><p style="line-height:1.7">Please keep your membership ID for future correspondence. Access to benefits follows your membership status and validity.</p><p>Warm regards,<br><strong>The Membership Team</strong><br>{H(society)}</p></td></tr><tr><td style="padding:20px 30px;background:#f8fafc;font-size:12px;line-height:1.7;color:#64748b">Sent to {H(recipientOverride??contact.Email)} in connection with your membership.<br>Manage email preferences in your member portal. Please do not reply to this automated message.</td></tr></table></td></tr></table></body></html>
 """;return new{subject,html,recipient=recipientOverride??contact.Email,memberName=name,membershipNumber=m.Number,kind,eligible=await Allowed(db,m,contact.Email,contact.User)};}
 public static void Map(RouteGroupBuilder api){var t=api.MapGroup("/societies/{tenant:guid}/member-welcome").RequireAuthorization(); t.AddEndpointFilter(async(ctx,next)=>{ctx.HttpContext.Response.Headers.CacheControl="no-store";return await next(ctx);});
 MemberSelfEmail.Map(t);
 t.MapGet("/templates",async(Guid tenant,Access a,AppDb db)=>{if(!await a.Platform()){await a.Member(tenant);if(!await Access.UnitsFor(db,tenant,a.UserId,"communications.send").AnyAsync())throw new AccessDeniedException();}return Templates;});
 t.MapGet("/members",async(Guid tenant,string? kind,string? search,Access a,AppDb db)=>{var q=MembershipIdentity.Filter(db,Scope(db,tenant,a.UserId,await a.Platform()),kind??"Individual");var term=(search??"").Trim().ToLower();return await(from m in q join p in db.Persons on m.PersonId equals p.Id where term==""||m.Number.ToLower().Contains(term)||p.FullName.ToLower().Contains(term) orderby m.JoinedAt descending select new{m.Id,m.Number,p.FullName,m.Status,m.PendingPayment,m.EffectiveFrom,m.EndsAt,lastWelcome=db.Outbox.Where(o=>o.TenantId==tenant&&o.MembershipId==m.Id&&o.TemplateName=="member-welcome-html").OrderByDescending(o=>o.CreatedAt).Select(o=>new{o.Status,o.CreatedAt,o.SentAt,o.Error}).FirstOrDefault()}).Take(100).ToListAsync();});
 t.MapGet("/preview",async(Guid tenant,Guid membershipId,string templateId,Access a,AppDb db,IConfiguration c)=>{var m=await Scope(db,tenant,a.UserId,await a.Platform()).SingleOrDefaultAsync(m=>m.Id==membershipId)??throw new AccessDeniedException();return await Preview(db,c,m,templateId);});
 t.MapPost("/send",async(Guid tenant,WelcomeSend r,Access a,AppDb db,IConfiguration c)=>{if(await a.Platform())await a.RequirePlatform();await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);var m=await Scope(db,tenant,a.UserId,await a.Platform()).SingleOrDefaultAsync(m=>m.Id==r.MembershipId)??throw new AccessDeniedException();if(!await db.Tenants.AnyAsync(t=>t.Id==tenant&&t.Status=="Active"))throw new DomainException("Society must be active");var contact=await Contact(db,m);if(!await Allowed(db,m,contact.Email,contact.User))throw new DomainException("An active, paid membership with a membership ID, valid email and email permission is required");var key="member-welcome:"+m.Id;if(await db.Outbox.AnyAsync(o=>o.TenantId==tenant&&o.IdempotencyKey==key))throw new DomainException("A welcome email already exists for this membership. Check its delivery status before sending again.");var preview=System.Text.Json.JsonSerializer.SerializeToElement(await Preview(db,c,m,r.TemplateId));var job=new Outbox{TenantId=tenant,UnitId=m.ChapterId,MembershipId=m.Id,SenderId=a.UserId,UserId=contact.User,Recipient=contact.Email,Subject=preview.GetProperty("subject").GetString()!,Body=preview.GetProperty("html").GetString()!,TemplateName="member-welcome-html",IdempotencyKey=key};db.Add(job);a.Audit(tenant,"membership.welcome.queued",m.Id,new{outboxId=job.Id,r.TemplateId,m.Number});await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(new{job.Id,job.Status});});
 }
 public static async Task<bool> CanDispatch(AppDb db,Outbox job){if(job.TenantId==null||job.MembershipId==null||job.SenderId==null)return false;var platform=await db.Users.AnyAsync(u=>u.Id==job.SenderId&&u.PlatformAdmin);var m=await Scope(db,job.TenantId.Value,job.SenderId.Value,platform).SingleOrDefaultAsync(m=>m.Id==job.MembershipId);if(m==null||!await PlatformPolicy.WorkAllowed(db,m.TenantId,"membership"))return false;var contact=await Contact(db,m);return string.Equals(contact.Email,job.Recipient,StringComparison.OrdinalIgnoreCase)&&await Allowed(db,m,contact.Email,contact.User);}
}
